(1, 'SearchFolder', 'http://172.25.0.5:7778/BBL/DMSAPIServices/SearchFolder/V1?wsdl', '<soapenv:Envelope xmlns:soapenv=\"http://schemas.xmlsoap.org/soap/envelope/\" xmlns:v1=\"http://www.bracbank.com/BBL/DMSAPIServices/SearchFolder/V1\" xmlns:v11=\"http://bracbank.com/utilityCommon/V1\">\r\n                               <soapenv:Header/>\r\n                               <soapenv:Body>\r\n                                  <v1:SearchFolderReq>\r\n                                     <v1:SearchFolderReqDetails>\r\n                                           <v1:header>\r\n                                           <v11:serviceId>UC-00006</v11:serviceId>\r\n                                           <v11:serviceName>SearchFolder</v11:serviceName>\r\n                                           <v11:sourceTimestamp>#sourceTimestamp#</v11:sourceTimestamp>\r\n                                           <v11:password>Ahj67#12i89kT!z</v11:password>\r\n                                           <v11:channelName>UBA</v11:channelName>\r\n                                           <v11:channelCode>IB</v11:channelCode>\r\n                                           <v11:globalTransactionId>#global_transaction_id#</v11:globalTransactionId>\r\n                                        </v1:header>\r\n                                        <v1:LookInFolder>#LookInFolder#</v1:LookInFolder>\r\n                                        <v1:IncludeSubFolder>N</v1:IncludeSubFolder>\r\n                                        <v1:Name>#name#</v1:Name>\r\n                                        <v1:SearchScope>0</v1:SearchScope>\r\n                                        <v1:ReferenceFlag>B</v1:ReferenceFlag>\r\n                                        <v1:StartFrom>1</v1:StartFrom>\r\n                                        <v1:NoOfRecordsToFetch>10</v1:NoOfRecordsToFetch>\r\n                                        <v1:OrderBy>2</v1:OrderBy>\r\n                                        <v1:SortOrde